import{_ as e,o as a,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"13. Operators and Expressions","description":"The Little Book of C — 13. Operators and Expressions","frontmatter":{"title":"13. Operators and Expressions","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Language Basics"],"description":"The Little Book of C — 13. Operators and Expressions","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":13,"sidebarWeight":13,"lang":"en-US","alternateEn":"/posts/c教程/en-US/02-Language Basics/013-Operators and Expressions","alternateZh":"/posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions"},"headers":[],"relativePath":"posts/c教程/en-US/02-Language Basics/013-Operators and Expressions.md","filePath":"posts/c教程/en-US/02-Language Basics/013-Operators and Expressions.md","lastUpdated":1790163617000}'),d={name:"posts/c教程/en-US/02-Language Basics/013-Operators and Expressions.md"};function o(i,t,p,r,c,l){return a(),s("div",null,[...t[0]||(t[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions)</p><p>Operators are the building blocks of computation in C. They let you perform arithmetic, compare values, manipulate bits, and combine logic, all in concise expressions. Once you understand how operators work and how they interact through precedence and associativity, you can write clear, efficient code that behaves exactly as you expect.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int a = 10, b = 3;</span></span>
<span class="line"><span>    printf(&quot;a + b = %d\\n&quot;, a + b);   // addition</span></span>
<span class="line"><span>    printf(&quot;a - b = %d\\n&quot;, a - b);   // subtraction</span></span>
<span class="line"><span>    printf(&quot;a * b = %d\\n&quot;, a * b);   // multiplication</span></span>
<span class="line"><span>    printf(&quot;a / b = %d\\n&quot;, a / b);   // integer division</span></span>
<span class="line"><span>    printf(&quot;a %% b = %d\\n&quot;, a % b);  // remainder (modulo)</span></span>
<span class="line"><span>    a += 5; // same as a = a + 5</span></span>
<span class="line"><span>    printf(&quot;a after += 5: %d\\n&quot;, a);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a + b = 13</span></span>
<span class="line"><span>a - b = 7</span></span>
<span class="line"><span>a * b = 30</span></span>
<span class="line"><span>a / b = 3</span></span>
<span class="line"><span>a % b = 1</span></span>
<span class="line"><span>a after += 5: 15</span></span></code></pre></div><h4 id="arithmetic-operators" tabindex="-1">Arithmetic Operators <a class="header-anchor" href="#arithmetic-operators" aria-label="Permalink to &quot;Arithmetic Operators&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th><th>Result</th></tr></thead><tbody><tr><td><code>+</code></td><td>Addition</td><td><code>4 + 3</code></td><td>7</td></tr><tr><td><code>-</code></td><td>Subtraction</td><td><code>10 - 6</code></td><td>4</td></tr><tr><td><code>*</code></td><td>Multiplication</td><td><code>2 * 5</code></td><td>10</td></tr><tr><td><code>/</code></td><td>Division</td><td><code>7 / 2</code></td><td>3 (integer division)</td></tr><tr><td><code>%</code></td><td>Modulo (remainder)</td><td><code>7 % 2</code></td><td>1</td></tr></tbody></table><p>Tip: If you use floating-point numbers (<code>float</code>,<code>double</code>), division produces decimals.</p><h4 id="relational-and-logical-operators" tabindex="-1">Relational and Logical Operators <a class="header-anchor" href="#relational-and-logical-operators" aria-label="Permalink to &quot;Relational and Logical Operators&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Operator</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>Relational</td><td><code>==</code></td><td><code>a == b</code></td><td>Equal</td></tr><tr><td><code>!=</code></td><td><code>a != b</code></td><td>Not equal</td><td></td></tr><tr><td><code>&lt;</code>,<code>&gt;</code>,<code>&lt;=</code>,<code>&gt;=</code></td><td><code>a &lt; b</code></td><td>Comparison</td><td></td></tr><tr><td>Logical</td><td><code>&amp;&amp;</code></td><td><code>a &amp;&amp; b</code></td><td>Logical AND</td></tr><tr><td>\`</td><td></td><td>\`</td><td>\`a</td></tr><tr><td><code>!</code></td><td><code>!a</code></td><td>Logical NOT</td><td></td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int age = 20;</span></span>
<span class="line"><span>if (age &gt;= 18 &amp;&amp; age &lt;= 60)</span></span>
<span class="line"><span>    printf(&quot;Adult\\n&quot;);</span></span></code></pre></div><h4 id="increment-and-decrement" tabindex="-1">Increment and Decrement <a class="header-anchor" href="#increment-and-decrement" aria-label="Permalink to &quot;Increment and Decrement&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, ++x); // prefix: increments, then uses value (6)</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x++); // postfix: uses value, then increments (6)</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);   // final value is 7</span></span></code></pre></div><h4 id="assignment-and-compound-operators" tabindex="-1">Assignment and Compound Operators <a class="header-anchor" href="#assignment-and-compound-operators" aria-label="Permalink to &quot;Assignment and Compound Operators&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>=</code></td><td>Assignment</td><td><code>x = 10</code></td></tr><tr><td><code>+=</code></td><td>Add and assign</td><td><code>x += 2</code></td></tr><tr><td><code>-=</code></td><td>Subtract and assign</td><td><code>x -= 3</code></td></tr><tr><td><code>*=</code></td><td>Multiply and assign</td><td><code>x *= 4</code></td></tr><tr><td><code>/=</code></td><td>Divide and assign</td><td><code>x /= 5</code></td></tr><tr><td><code>%=</code></td><td>Modulo and assign</td><td><code>x %= 6</code></td></tr></tbody></table><p>These save typing and make intent clearer.</p><h4 id="bitwise-operators" tabindex="-1">Bitwise Operators <a class="header-anchor" href="#bitwise-operators" aria-label="Permalink to &quot;Bitwise Operators&quot;">​</a></h4><p>C gives you direct access to bits, useful for systems, embedded, or optimization tasks.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>&amp;</code></td><td>AND</td><td><code>a &amp; b</code></td></tr><tr><td>\`</td><td>\`</td><td>OR</td></tr><tr><td><code>^</code></td><td>XOR</td><td><code>a ^ b</code></td></tr><tr><td><code>~</code></td><td>NOT</td><td><code>~a</code></td></tr><tr><td><code>&lt;&lt;</code></td><td>Left shift</td><td><code>a &lt;&lt; 1</code></td></tr><tr><td><code>&gt;&gt;</code></td><td>Right shift</td><td><code>a &gt;&gt; 2</code></td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int mask = 0b0010;</span></span>
<span class="line"><span>int num = 0b1011;</span></span>
<span class="line"><span>int result = num &amp; mask;  // checks if the 2nd bit is set</span></span></code></pre></div><h4 id="precedence-and-associativity" tabindex="-1">Precedence and Associativity <a class="header-anchor" href="#precedence-and-associativity" aria-label="Permalink to &quot;Precedence and Associativity&quot;">​</a></h4><p>When you write complex expressions, C follows operator precedence rules. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int result = 2 + 3 * 4; // result is 14, not 20</span></span></code></pre></div><p><code>*</code> has higher precedence than<code>+</code>, so it runs first.</p><p>Use parentheses to make intentions clear:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int result = (2 + 3) * 4; // result is 20</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Operators are where logic meets the machine. They translate mathematical ideas and control decisions into instructions the CPU executes directly. Understanding how expressions are built and evaluated helps you:</p><ul><li>Write compact, efficient code</li><li>Avoid precedence mistakes</li><li>Control exactly what your program computes</li></ul><p>In low-level work (like bitwise operations or embedded systems), operator mastery is essential.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Write a small program that takes two integers and prints their:</p><ul><li>Sum</li><li>Difference</li><li>Product</li><li>Quotient</li><li>Remainder</li></ul><p>Modify it to print results as floating-point values.</p><p>Use logical operators to test if both numbers are positive.</p><p>Try combining bitwise operations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d\\n&quot;, 5 &amp; 3);  // AND</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 5 | 3);  // OR</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 5 ^ 3);  // XOR</span></span></code></pre></div><p>Experiment with parentheses and operator order until you can predict every result.</p><p>Operators are where C’s simplicity meets its power, a small set of symbols that give you total control over computation, logic, and even raw bits.</p>`,42)])])}const b=e(d,[["render",o]]);export{u as __pageData,b as default};
